SELECT i.inquiry_id AS inquiryId, i.title, i.category, i.status, i.created_at AS createdAt, u.name AS userName, u.user_id AS userId FROM inquiries i LEFT JOIN users u ON i.user_id = u.user_id
WHERE i.status = #{status}
ORDER BY i.created_at DESC LIMIT #{limit} OFFSET #{offset}
